  ('a492000c-a567-578c-a96c-19a880483bd0', 'essential_medical:core:pons:noun:ess-core-pons-001', '645e75ba-8333-52a4-8045-7c1cfa4ae278', 'The textbook figure labels the pons beside the neighboring tissue.', 'pons', 'Here the term names the brainstem bulge between midbrain and medulla.', '这里指脑桥。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('61cf826a-d9c2-5014-8b41-08f783b4325a', 'essential_medical:core:neurology:noun:ess-core-neurology-001', '330b0991-ad99-5192-8bc2-fee975f293e2', 'After history taking, the intern wrote the neurology into the problem list.', 'neurology', 'Here the term names the study of the nervous system and its diseases.', '这里指神经病学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4efd4bff-ff57-50cc-bc05-2c3e7a0b1abb', 'essential_medical:core:cerebellum:noun:ess-core-cerebellum-001', '4086e3a1-bbd4-51d4-a474-167038b8c058', 'The lecture contrasted a healthy cerebellum with the diseased counterpart.', 'cerebellum', 'Here the term names the hindbrain structure that coordinates movement.', '这里指小脑。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('f65085aa-acf4-51aa-9090-99a7c6b676b7', 'essential_medical:core:acetylcholine:noun:ess-core-acetylcholine-001', '74aacc15-a320-5c46-a861-fd313000c609', 'In class the tutor pointed to the acetylcholine while explaining the adjacent organ.', 'acetylcholine', 'Here the term names a neurotransmitter at neuromuscular and many autonomic synapses.', '这里指乙酰胆碱。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('9ff63c44-3af9-50fb-8f73-b598c93b0f43', 'essential_medical:core:brain-stem:phrase:ess-core-brain-stem-001', '2d31e58d-bb0d-56b0-9c7f-26422eb9f91e', 'The case note named the brain stem before describing what happened next.', 'brain stem', 'Here the term names midbrain, pons, and medulla connecting brain and cord.', '这里指脑干。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('45f2392b-53da-58fd-b1ca-c8d2b4f6fe4f', 'essential_medical:core:efferent:adjective:ess-core-efferent-001', 'c0650681-fa9c-587f-ae41-9037099cd747', 'On the ward, the sign was documented as efferent after the examination.', 'efferent', 'The classroom note used this word to say the finding was carrying impulses away from a center.', '课堂记录把这一发现写成「传出的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('018e223a-68b9-50e3-b07c-63a206937463', 'essential_medical:core:medulla-oblongata:phrase:ess-core-medulla-oblongata-001', '18d6f980-a39e-52cd-b03c-ff063280afd0', 'The diagram of the medulla oblongata was the first figure in that chapter.', 'medulla oblongata', 'Here the term names the lowest brainstem, continuous with the spinal cord.', '这里指延髓。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('618fc82b-768a-5851-b4ad-c361d4c4f6b3', 'essential_medical:core:afferent:adjective:ess-core-afferent-001', '8a96d893-ce7c-5949-b3b2-90e1cda2a89f', 'Her presentation stayed afferent from admission through the first night.', 'afferent', 'The classroom note used this word to say the finding was carrying impulses toward a center.', '课堂记录把这一发现写成「传入的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('377d8182-10ba-5721-9a50-a38b0184c64f', 'essential_medical:core:meninx:noun:ess-core-meninx-001', '4b3db42b-2695-5246-bdec-d54384814bce', 'The textbook figure labels the meninx beside the neighboring tissue.', 'meninx', 'Here the term names one of the meninges covering brain or cord.', '这里指脑膜。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('f7395ad1-a29d-5272-8116-7e13bcc16b3a', 'essential_medical:core:parasympathetic:adjective:ess-core-parasympathetic-001', 'b3643247-47e9-567f-8edb-62bca974bae7', 'Students compared a parasympathetic pattern with the opposite classroom example.', 'parasympathetic', 'The classroom note used this word to say the finding was relating to the rest-and-digest autonomic division.', '课堂记录把这一发现写成「副交感的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('fc1db592-75a7-5127-8b60-f43c45c3ae58', 'essential_medical:core:cauda-equina:phrase:ess-core-cauda-equina-001', '7f49275f-4f2c-5b8f-8f95-7a723c750bd3', 'The case note named the cauda equina before describing what happened next.', 'cauda equina', 'Here the term names the bundle of lumbar and sacral roots below the cord.', '这里指马尾。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('f8b94828-74e5-5850-9bf5-26d657973177', 'essential_medical:core:dura:noun:ess-core-dura-001', '3a5bebb1-258d-5892-999f-aac5ab390af6', 'In class the tutor pointed to the dura while explaining the adjacent organ.', 'dura', 'Here the term names the tough outer meninx; dura mater.', '这里指硬膜。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('617e059d-53e2-59b6-a8b6-8112b561efcb', 'essential_medical:core:sympathetic:adjective:ess-core-sympathetic-001', 'a1e5ddc9-8db1-552e-a34b-bdd74356fe1c', 'The case stem described a sympathetic change that students had to interpret.', 'sympathetic', 'The classroom note used this word to say the finding was relating to the fight-or-flight autonomic division.', '课堂记录把这一发现写成「交感的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('051b6370-e95e-58df-a657-708892ed50e6', 'essential_medical:core:mater:noun:ess-core-mater-001', '27d6310f-883a-5443-9530-47180b99812d', 'A short case note mentioned the mater before listing later findings.', 'mater', 'Here the term names mater in dura/pia/arachnoid mater, a meningeal layer.', '这里指膜（脑脊膜）。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d1e5c68a-c24f-5258-8c12-ae479e937184', 'essential_medical:core:arachnoid:noun:ess-core-arachnoid-001', '995c810c-3cb2-526e-be82-34448ff5b2c0', 'Students were asked to locate the arachnoid on the classroom diagram.', 'arachnoid', 'Here the term names the middle meningeal layer.', '这里指蛛网膜。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('dd33f64d-2c5d-5511-b50d-1b3a46dcc7ae', 'essential_medical:core:ganglion:noun:ess-core-ganglion-001', '02171e60-a57c-569f-ac2f-c9b5cff27401', 'The ward round paused on the ganglion so juniors could name it correctly.', 'ganglion', 'Here the term names a cluster of nerve-cell bodies outside the CNS.', '这里指神经节。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('557e3685-43bb-59a2-b330-16dec67fb13e', 'essential_medical:core:pia-mater:phrase:ess-core-pia-mater-001', '0f56f3ba-b97f-55e9-8354-6f2794ac9adc', 'The case note named the pia mater before describing what happened next.', 'pia mater', 'Here the term names the delicate inner meninx on the brain and cord surface.', '这里指软膜。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('2c1eb157-684e-57f2-878a-7e30e3aa6362', 'essential_medical:core:plexus:noun:ess-core-plexus-001', '2ff6e6b4-3cea-5212-9a6a-a5126c039247', 'After history taking, the intern wrote the plexus into the problem list.', 'plexus', 'Here the term names a network of nerves or vessels.', '这里指丛。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d9d5c165-ede2-5d48-a18e-ddc656d844bb', 'essential_medical:core:lumbar-puncture:phrase:ess-core-lumbar-puncture-001', 'ee60078c-be98-5c66-a566-c485f4b6b8ef', 'The diagram of the lumbar puncture was the first figure in that chapter.', 'lumbar puncture', 'Here the term names needle sampling of CSF in the lumbar sac.', '这里指腰椎穿刺。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('01513836-f4ef-5deb-beff-5059182f7265', 'essential_medical:core:dendrite:noun:ess-core-dendrite-001', '1903c828-407c-5acb-b5d3-9bfe7491dc1c', 'In class the tutor pointed to the dendrite while explaining the adjacent organ.', 'dendrite', 'Here the term names the branching process that receives synaptic input.', '这里指树突。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('660ef609-5cff-5d15-b44f-2357849ef978', 'essential_medical:core:electrical-charge:phrase:ess-core-electrical-charge-001', '7b1f0f63-8eab-59b8-b810-a46b25ccda70', 'The textbook treats the electrical charge as core vocabulary, not exam trivia.', 'electrical charge', 'Here the term names the charged state that underlies nerve action potentials.', '这里指电荷。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('560725b5-5ff6-54ec-88bc-55a04ae33034', 'essential_medical:core:axon:noun:ess-core-axon-001', 'ecd96c97-4b1f-5298-a059-7e268ba8f315', 'A short case note mentioned the axon before listing later findings.', 'axon', 'Here the term names the long process that carries a nerve impulse away.', '这里指轴突。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('b4049f08-da7e-5627-8d0e-9de12527c710', 'essential_medical:core:myelin:noun:ess-core-myelin-001', 'c722656c-ec26-5128-86f7-510fd3cbc424', 'Students were asked to locate the myelin on the classroom diagram.', 'myelin', 'Here the term names the insulating sheath around many axons.', '这里指髓鞘质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('aaf39cba-1b55-5dc2-907f-6d90811067b7', 'essential_medical:core:neurilemma:noun:ess-core-neurilemma-001', '0ab48ca5-b5d8-556b-8b9f-54f69489ac99', 'The ward round paused on the neurilemma so juniors could name it correctly.', 'neurilemma', 'Here the term names the Schwann-cell sheath around a peripheral axon.', '这里指神经膜。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4da98763-9a83-5dc1-98de-521ca876da85', 'essential_medical:core:synapse:noun:ess-core-synapse-001', 'cb5a3353-7d14-5118-a240-b42517446068', 'The textbook figure labels the synapse beside the neighboring tissue.', 'synapse', 'Here the term names the junction where one neuron signals another.', '这里指突触。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('297920bd-f719-57f9-955d-f57c2276c23d', 'essential_medical:core:white-matter:phrase:ess-core-white-matter-001', '597b243a-1c63-5972-8de1-97afcdb9b92d', 'On rounds the registrar asked for the function of the white matter.', 'white matter', 'Here the term names CNS tissue rich in myelinated axons.', '这里指白质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('834da682-e5e7-5bc4-b547-d30a8ce07211', 'essential_medical:core:gray-matter:phrase:ess-core-gray-matter-001', '21bbd2a0-3fb5-58e0-9a43-dbd4713bbdf0', 'The textbook treats the gray matter as core vocabulary, not exam trivia.', 'gray matter', 'Here the term names CNS tissue rich in cell bodies.', '这里指灰质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7d30ee10-d652-59a7-8246-6eceb9b2b5d3', 'essential_medical:core:neurotransmitter:noun:ess-core-neurotransmitter-001', '344882fe-1008-5101-8a07-11a93126999e', 'In class the tutor pointed to the neurotransmitter while explaining the adjacent organ.', 'neurotransmitter', 'Here the term names a chemical signal released at a synapse.', '这里指神经递质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('dd3d89b8-3556-59ff-958d-08695057883a', 'essential_medical:core:neuroglia:noun:ess-core-neuroglia-001', 'e4c384fd-fbe5-5e19-9d79-285852f79a30', 'The chapter on body structure opens with the neuroglia as a teaching example.', 'neuroglia', 'Here the term names the supporting cells of the nervous system.', '这里指神经胶质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('93175881-ff10-5e97-a2cf-4b1392fb838d', 'essential_medical:core:astrocyte:noun:ess-core-astrocyte-001', '325d92d4-005d-56a6-b22a-8cc60973d897', 'A short case note mentioned the astrocyte before listing later findings.', 'astrocyte', 'Here the term names a star-shaped glial cell of the CNS.', '这里指星形胶质细胞。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('ac3ec2af-c7be-5e4d-a639-ae538e6dde10', 'essential_medical:core:glioma:noun:ess-core-glioma-001', '5a266fed-89e2-5183-8ba5-b8ebdc026e25', 'Students were asked to locate the glioma on the classroom diagram.', 'glioma', 'Here the term names a tumor of glial cells.', '这里指胶质瘤。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a46c6749-f2a3-5779-9b0f-01890c4eaee9', 'essential_medical:core:microglia:noun:ess-core-microglia-001', '01e5f4ec-82af-5c0f-99de-fdf7c0d21be9', 'The ward round paused on the microglia so juniors could name it correctly.', 'microglia', 'Here the term names the resident immune cells of the CNS.', '这里指小胶质细胞。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d8ec1497-dc8d-5009-a42f-f754240494fb', 'essential_medical:core:oligodendroglia:noun:ess-core-oligodendroglia-001', '63e64280-831a-5bcd-af01-dc96a43407d7', 'The textbook figure labels the oligodendroglia beside the neighboring tissue.', 'oligodendroglia', 'Here the term names CNS cells that form myelin.', '这里指少突胶质细胞。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('2925a072-ddd6-5b46-8bfe-23e613300f25', 'essential_medical:core:cerebrum:noun:ess-core-cerebrum-001', '1636f4cc-4d1f-5800-8257-0cd3f5cbc1f6', 'After history taking, the intern wrote the cerebrum into the problem list.', 'cerebrum', 'Here the term names the large paired hemispheres of the brain.', '这里指大脑。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d2e94e1a-45fe-5180-83ab-7c731b897128', 'essential_medical:core:convolution:noun:ess-core-convolution-001', '72df45bc-f6ea-525f-acff-5ca670db025a', 'The lecture contrasted a healthy convolution with the diseased counterpart.', 'convolution', 'Here the term names a gyrus; a fold of the cerebral cortex.', '这里指脑回。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('aea12f5d-8ed5-58c8-af38-9c5be9c55738', 'essential_medical:core:peripheral-nervous-system:phrase:ess-core-peripheral-nervous-system-001', '0b52fba0-9b42-5d43-9609-05b1d61e58ad', 'Students had to explain the peripheral nervous system in one plain sentence of their own.', 'peripheral nervous system', 'Here the term names nerves and ganglia outside the brain and cord.', '这里指周围神经系统。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('cb1165ca-75c2-58f4-ad85-8e463d3c8bf7', 'essential_medical:core:autonomic-nervous-system:phrase:ess-core-autonomic-nervous-system-001', 'd405cdbd-2122-56d8-8ce0-c0652c14138a', 'The diagram of the autonomic nervous system was the first figure in that chapter.', 'autonomic nervous system', 'Here the term names the involuntary visceral motor system.', '这里指自主神经系统。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1f244ab9-19ed-5bd8-9c2a-81508c14bb07', 'essential_medical:core:visceral-nervous-system:phrase:ess-core-visceral-nervous-system-001', '3c90c3ad-3eb7-560b-995d-c992b73260f0', 'On rounds the registrar asked for the function of the visceral nervous system.', 'visceral nervous system', 'Here the term names the nerves supplying internal organs.', '这里指内脏神经系统。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('8852fad9-485c-534b-9533-e640c6b3059b', 'essential_medical:core:groove:noun:ess-core-groove-001', '9201d0a4-c4f0-5316-bb93-ff9de87e995b', 'Students were asked to locate the groove on the classroom diagram.', 'groove', 'Here the term names a shallow furrow on a bone or organ surface.', '这里指沟。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4a27dba8-4656-5f6d-a826-e686addc8448', 'essential_medical:core:fissure:noun:ess-core-fissure-001', '53f300d4-9e13-5b69-9aa7-682b63c83bcb', 'The ward round paused on the fissure so juniors could name it correctly.', 'fissure', 'Here the term names a deeper cleft, as between cerebral hemispheres.', '这里指裂。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('20ae6df3-4f73-5676-8fc9-bb5bf9cbc6bc', 'essential_medical:core:sulcus:noun:ess-core-sulcus-001', '626e516c-f190-5278-943d-cc78b72d2e14', 'The textbook figure labels the sulcus beside the neighboring tissue.', 'sulcus', 'Here the term names a groove between gyri of the cortex.', '这里指沟。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('530e5656-4263-501a-8e28-d066a1e3ebbf', 'essential_medical:core:thalamus:noun:ess-core-thalamus-001', '7c11ae8f-eb82-596c-ac36-030d856ec275', 'After history taking, the intern wrote the thalamus into the problem list.', 'thalamus', 'Here the term names the diencephalic relay for sensory pathways to cortex.', '这里指丘脑。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null)
